package io.argos.sample.common;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Properties;

/**
 * App name and version from {@code io/argos/sample/build-info.properties}, generated by the
 * argos.sample-app Gradle plugin into every app (exposed at GET /api/version, F-A21).
 */
public final class BuildInfo {

  /** Classpath resource written by the build. */
  public static final String RESOURCE = "io/argos/sample/build-info.properties";

  private final String app;
  private final String version;

  public BuildInfo(String app, String version) {
    this.app = app;
    this.version = version;
  }

  /**
   * Loads the resource through the class loader of {@code anchor} (the app's main class). The first
   * resource wins, so an app that depends on another app's jar (shop-heavy, the WAR apps) reports
   * its own name: its classes come first on the class path.
   */
  public static BuildInfo load(Class<?> anchor, String fallbackApp) {
    ClassLoader loader = anchor.getClassLoader();
    Properties properties = new Properties();
    try (InputStream in = loader == null ? null : loader.getResourceAsStream(RESOURCE)) {
      if (in != null) {
        try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8)) {
          properties.load(reader);
        }
      }
    } catch (IOException e) {
      throw new IllegalStateException("Cannot read " + RESOURCE, e);
    }
    return new BuildInfo(
        properties.getProperty("app", fallbackApp), properties.getProperty("version", "unknown"));
  }

  public String app() {
    return app;
  }

  public String version() {
    return version;
  }
}
